contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        bytes32 assertionId,
        address disputeCaller,
        bytes32 identifier,
        uint256 time,
        bytes memory ancillaryData
    ) public {
        // Read the assertion policy for a caller supplied id.
        EscalationManagerInterface.AssertionPolicy memory policy = c.getAssertionPolicy(assertionId);

        // Read whether the given dispute caller is allowed.
        bool disputeAllowed = c.isDisputeAllowed(assertionId, disputeCaller);

        // Attempt a price request from the wrong caller: it must fail because
        // requestPrice is restricted to the optimistic asserter.
        bool requestReverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            requestReverted = false;
        } catch {
            requestReverted = true;
        }

        assert(
            policy.blockAssertion == false &&
            policy.arbitrateViaEscalationManager == false &&
            policy.discardOracle == false &&
            policy.validateDisputers == false &&
            disputeAllowed == true &&
            requestReverted == true
        );
    }
}

