contract InvMutTest {
    C c;
    event PriceRequestAdded(bytes32 indexed identifier, uint256 time, bytes ancillaryData);

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData, address caller) public {
        require(caller == address(this), "caller must be this contract");

        bytes32 expectedTopic = keccak256("PriceRequestAdded(bytes32,uint256,bytes)");
        uint256 expectedTime = time;
        bytes32 expectedId = keccak256(abi.encode(identifier));
        bytes32 expectedDataHash = keccak256(abi.encode(ancillaryData));

        vm.recordLogs();
        c.requestPrice(identifier, time, ancillaryData);
        Vm.Log[] memory logs = vm.getRecordedLogs();

        bool found;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].topics.length == 2 && logs[i].topics[0] == expectedTopic) {
                if (logs[i].topics[1] == expectedId) {
                    (uint256 emittedTime, bytes memory emittedData) = abi.decode(logs[i].data, (uint256, bytes));
                    if (emittedTime == expectedTime && keccak256(abi.encode(emittedData)) == expectedDataHash) {
                        found = true;
                        break;
                    }
                }
            }
        }

        assert(found);
    }
}

