contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 identifier, uint256 time, bytes memory ancillaryData, bool useAllowed) public {
        // The optimistic asserter is the only address allowed to call requestPrice.
        address allowed = address(c.optimisticAsserter());

        // Only read-only calls are made before the deciding call.
        // No state-changing preconditions: requestPrice is the single state-changing call under test.

        bool reverted;
        if (useAllowed) {
            // The allowed sender path: msg.sender for all calls is this test contract.
            // To become the authorized caller, the test contract must be the asserter.
            // Since c.optimisticAsserter() may not be this contract, the only way to
            // exercise the success path is to rely on this test contract being the
            // optimist asserter. If it is not, this branch will still revert and the
            // rule below remains true: an unauthorized sender reverts.
            try c.requestPrice(identifier, time, ancillaryData) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // A sender other than optimisticAsserter is not available because
            // msg.sender is always this test contract. We can still check the general
            // invariant: whenever the call succeeds, the emitted event data is exactly
            // the input data. Since we cannot emit-spy, the assert is expressed on
            // the revert behavior.
            try c.requestPrice(identifier, time, ancillaryData) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule: a call to requestPrice succeeds iff the caller is the
        // optimistic asserter recorded by the contract. Here the caller is always
        // this test contract, so success occurs exactly when this contract is the
        // configured optimistic asserter. In all other cases it must revert.
        bool callerIsAsserter = (address(this) == allowed);
        assert(reverted == !callerIsAsserter);
    }

    receive() external payable {}
}

